package com.eidolon.sc.mobile;
import android.content.*;import android.database.*;import android.database.sqlite.*;import org.json.*;import java.util.*;import java.time.*;import java.io.*;

/** Additive v18 data. No chat/affinity/memory writes; all public mutations are transactional. */
final class SocialStore {
 static final Object LOCK=new Object();
 static void create(SQLiteDatabase db){
  db.execSQL("CREATE TABLE social_meta(key TEXT PRIMARY KEY,body TEXT NOT NULL)");
  db.execSQL("CREATE TABLE social_posts(id TEXT PRIMARY KEY,character TEXT NOT NULL,day TEXT NOT NULL,published INTEGER NOT NULL,body TEXT NOT NULL,UNIQUE(character,day))");db.execSQL("CREATE INDEX social_posts_at ON social_posts(published DESC)");
  db.execSQL("CREATE TABLE social_comments(id TEXT PRIMARY KEY,post TEXT NOT NULL UNIQUE,body TEXT NOT NULL)");
  db.execSQL("CREATE TABLE social_circle(id TEXT PRIMARY KEY,post TEXT NOT NULL,shown INTEGER NOT NULL,body TEXT NOT NULL)");
  db.execSQL("CREATE TABLE social_tasks(id TEXT PRIMARY KEY,character TEXT NOT NULL,kind TEXT NOT NULL,target TEXT NOT NULL,day TEXT NOT NULL,due INTEGER NOT NULL,expires INTEGER NOT NULL,state TEXT NOT NULL,token TEXT NOT NULL DEFAULT '',body TEXT NOT NULL,error TEXT NOT NULL DEFAULT '',started INTEGER NOT NULL DEFAULT 0,finished INTEGER NOT NULL DEFAULT 0)");db.execSQL("CREATE INDEX social_tasks_due ON social_tasks(state,due)");
  db.execSQL("CREATE TABLE social_plans(day TEXT PRIMARY KEY,at INTEGER NOT NULL)");
  db.execSQL("CREATE TABLE social_usage(id TEXT PRIMARY KEY,day TEXT NOT NULL,kind TEXT NOT NULL,character TEXT NOT NULL,at INTEGER NOT NULL)");
 }
 static JSONObject meta(ChatStore s,String key)throws Exception{try(Cursor r=s.getReadableDatabase().rawQuery("SELECT body FROM social_meta WHERE key=?",new String[]{key})){return r.moveToFirst()?new JSONObject(r.getString(0)):new JSONObject();}}
 static void meta(ChatStore s,String key,JSONObject value)throws IOException{ContentValues v=new ContentValues();v.put("key",key);v.put("body",value.toString());if(s.getWritableDatabase().insertWithOnConflict("social_meta",null,v,SQLiteDatabase.CONFLICT_REPLACE)<0)throw new IOException("朋友圈或天气设置保存失败");}
 static JSONObject config(ChatStore s)throws Exception{JSONObject raw=meta(s,"moments");return SocialData.settings(raw).put("revision",raw.optLong("revision"));}
 static JSONObject weatherConfig(ChatStore s)throws Exception{JSONObject w=meta(s,"weather");return new JSONObject().put("enabled",w.optBoolean("enabled")).put("tokyo",w.optBoolean("tokyo",true)).put("user",w.optBoolean("user",true)).put("host",w.optString("host")).put("auth",w.optString("auth","jwt")).put("kid",w.optString("kid")).put("developer",w.optString("developer")).put("project",w.optString("project")).put("revision",w.optLong("revision")).put("credentialSet",w.optString("credentialSet"));}
 static JSONObject city(ChatStore s)throws Exception{JSONObject c=meta(s,"city");return c.has("name")?SocialData.city(c):null;}
 static long count(ChatStore s,String sql,String...args){try(Cursor c=s.getReadableDatabase().rawQuery(sql,args)){return c.moveToFirst()?c.getLong(0):0;}}
 static String budgetDay(ChatStore s,long now,boolean advance)throws Exception{String today=SocialData.day(now),high=meta(s,"budgetClock").optString("day",today),day=SocialData.budgetDay(today,high);if(advance&&day.compareTo(high)>=0)meta(s,"budgetClock",new JSONObject().put("day",day));return day;}
 static long used(ChatStore s,String day,String kind){return count(s,"SELECT count(*) FROM social_usage WHERE day=? AND kind=?",day,kind);}
 static JSONObject post(ChatStore s,String id)throws Exception{try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM social_posts WHERE id=?",new String[]{id})){if(!c.moveToFirst())throw new IOException("动态不存在或已清理");return new JSONObject(c.getString(0));}}
 static JSONObject commentById(ChatStore s,String id)throws Exception{try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM social_comments WHERE id=?",new String[]{id})){return c.moveToFirst()?new JSONObject(c.getString(0)):null;}}
 static JSONObject postComment(ChatStore s,String post)throws Exception{try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM social_comments WHERE post=?",new String[]{post})){return c.moveToFirst()?new JSONObject(c.getString(0)):null;}}
 static void requireEnabled(ChatStore s)throws Exception{if(!config(s).getBoolean("enabled"))throw new IOException("朋友圈已关闭，请在设置开启");}
 static JSONObject saveConfig(ChatStore s,JSONObject args,Set<String> known,long now)throws Exception{synchronized(LOCK){SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{JSONObject cfg=SocialData.settings(args),old=config(s);if(args.optLong("revision",-1)!=old.getLong("revision"))throw new IOException("朋友圈设置已改变，请重新读取后保存");JSONArray a=cfg.getJSONArray("characters");Set<String> seen=new HashSet<>();for(int i=0;i<a.length();i++)if(!known.contains(a.getString(i))||!seen.add(a.getString(i)))throw new IOException("参与角色无效");cfg.put("revision",old.optLong("revision")+1);meta(s,"moments",cfg);db.execSQL("UPDATE social_tasks SET state='CANCELLED',token='',finished=?,error='配置已改变，已开始的请求不自动重发' WHERE state='RUNNING'",new Object[]{now});db.setTransactionSuccessful();return cfg;}finally{db.endTransaction();}}}
 static JSONObject task(ChatStore s,String id)throws Exception{try(Cursor r=s.getReadableDatabase().rawQuery("SELECT id,character,kind,target,day,due,expires,state,token,body,error,started,finished FROM social_tasks WHERE id=?",new String[]{id})){if(!r.moveToFirst())return null;return new JSONObject().put("id",r.getString(0)).put("character",r.getString(1)).put("kind",r.getString(2)).put("target",r.getString(3)).put("day",r.getString(4)).put("due",r.getLong(5)).put("expires",r.getLong(6)).put("state",r.getString(7)).put("token",r.getString(8)).put("body",new JSONObject(r.getString(9))).put("error",r.getString(10)).put("started",r.getLong(11)).put("finished",r.getLong(12));}}
 static String addTask(ChatStore s,String who,String kind,String target,String day,long due,long expires,JSONObject body){String id=UUID.randomUUID().toString();ContentValues v=new ContentValues();v.put("id",id);v.put("character",who);v.put("kind",kind);v.put("target",target);v.put("day",day);v.put("due",due);v.put("expires",expires);v.put("state","PENDING");v.put("body",body.toString());s.getWritableDatabase().insertOrThrow("social_tasks",null,v);return id;}
 static String due(ChatStore s,long now){try(Cursor c=s.getReadableDatabase().rawQuery("SELECT id FROM social_tasks WHERE state='PENDING' AND due<=? AND expires>? ORDER BY due LIMIT 1",new String[]{""+now,""+now})){return c.moveToFirst()?c.getString(0):"";}}
 static JSONArray pending(ChatStore s)throws Exception{JSONArray a=new JSONArray();try(Cursor r=s.getReadableDatabase().rawQuery("SELECT id FROM social_tasks WHERE state='PENDING' ORDER BY due LIMIT 50",null)){while(r.moveToNext())a.put(task(s,r.getString(0)));}return a;}
 static void finish(ChatStore s,String id,String token,String state,String error,long now){ContentValues v=new ContentValues();v.put("state",state);v.put("token","");v.put("error",MediaData.cut(error,300));v.put("finished",now);s.getWritableDatabase().update("social_tasks",v,"id=? AND state='RUNNING' AND token=?",new String[]{id,token});}
 static String claim(ChatStore s,JSONObject row,JSONObject cfg,long now)throws Exception{SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{if(!config(s).getBoolean("enabled")||config(s).getLong("revision")!=cfg.getLong("revision"))return "";String day=budgetDay(s,now,true),kind=row.getString("kind");int limit=cfg.getInt(kind.equals("post")?"perDay":"repliesPerDay");if(kind.equals("post")&&!row.getString("day").equals(SocialData.day(now))||used(s,day,kind)>=limit)return "";String token=UUID.randomUUID().toString();ContentValues v=new ContentValues();v.put("state","RUNNING");v.put("token",token);v.put("started",now);if(db.update("social_tasks",v,"id=? AND state='PENDING' AND due<=? AND expires>?",new String[]{row.getString("id"),""+now,""+now})!=1)return "";ContentValues usage=new ContentValues();usage.put("id",row.getString("id"));usage.put("day",day);usage.put("kind",kind);usage.put("character",row.getString("character"));usage.put("at",now);db.insertOrThrow("social_usage",null,usage);db.setTransactionSuccessful();return token;}finally{db.endTransaction();}}
 static void recover(ChatStore s,long now){s.getWritableDatabase().execSQL("UPDATE social_tasks SET state='FAILED',token='',finished=?,error='进程中断，服务计费结果未知，未自动重发' WHERE state='RUNNING'",new Object[]{now});}
 static void expire(ChatStore s,long now){s.getWritableDatabase().execSQL("UPDATE social_tasks SET state='SKIPPED',finished=?,error='已过有效期，未补发' WHERE state='PENDING' AND expires<=?",new Object[]{now,now});}
 static long contact(ChatStore s)throws Exception{long now=System.currentTimeMillis(),at=count(s,"SELECT coalesce(max(sent_at),0) FROM messages WHERE role='assistant' AND reach_at=0 AND sent_at<=?",""+now);JSONArray calls=CallStore.all(s);for(int i=0;i<calls.length();i++){JSONObject r=calls.getJSONObject(i);long connected=r.optLong("connectedAt"),ended=r.optLong("endedAt");if(connected>0&&connected<=now)at=Math.max(at,ended>=connected&&ended<=now?ended:connected);}return at;}
 static boolean hasTurn(ChatStore s,String who){return count(s,"SELECT count(*) FROM messages WHERE character=? AND role='assistant' AND reach_at=0",who)>0;}
 static boolean hasPending(ChatStore s,String who){return count(s,"SELECT count(*) FROM pending_replies WHERE character=? AND status IN ('collecting','generating','waiting','failed')",who)>0;}
 static JSONObject like(ChatStore s,String id,boolean liked,long now)throws Exception{synchronized(LOCK){requireEnabled(s);JSONObject p=post(s,id);if(p.getLong("published")>now)throw new IOException("动态尚未发布");p.put("liked",liked);ContentValues v=new ContentValues();v.put("body",p.toString());s.getWritableDatabase().update("social_posts",v,"id=?",new String[]{id});return shown(s,p,now);}}
 static JSONObject addComment(ChatStore s,String post,String text,long now,boolean affinity)throws Exception{synchronized(LOCK){SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{requireEnabled(s);JSONObject p=post(s,post);if(p.getLong("published")>now)throw new IOException("动态尚未发布");if(postComment(s,post)!=null)throw new IOException("这条动态已经有你的评论，请先删除再评论");String id=UUID.randomUUID().toString(),who=p.getString("character");JSONObject row=new JSONObject().put("id",id).put("post",post).put("text",SocialData.comment(text)).put("at",now);ContentValues v=new ContentValues();v.put("id",id);v.put("post",post);v.put("body",row.toString());db.insertOrThrow("social_comments",null,v);long due=SocialData.replyAt(now,s.personal(),who,affinity,new Random());if(due>0&&config(s).getInt("repliesPerDay")>0)addTask(s,who,"reply",id,SocialData.day(now),due,due+2*SocialData.HOUR,new JSONObject().put("post",post));db.setTransactionSuccessful();return row;}finally{db.endTransaction();}}}
 static void deleteComment(ChatStore s,String id,long now)throws Exception{synchronized(LOCK){requireEnabled(s);SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{db.delete("social_comments","id=?",new String[]{id});db.execSQL("UPDATE social_tasks SET state='CANCELLED',token='',finished=?,error='评论已删除' WHERE target=? AND kind='reply' AND state IN ('PENDING','RUNNING')",new Object[]{now,id});db.setTransactionSuccessful();}finally{db.endTransaction();}}}
 static JSONObject shown(ChatStore s,JSONObject p,long now)throws Exception{JSONObject out=new JSONObject(p.toString());JSONArray circle=new JSONArray();try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM social_circle WHERE post=? AND shown<=? ORDER BY shown,id",new String[]{p.getString("id"),""+now})){while(c.moveToNext())circle.put(new JSONObject(c.getString(0)));}out.put("circle",circle);JSONObject comment=postComment(s,p.getString("id"));if(comment!=null&&comment.has("reply")&&comment.optLong("replyAt")>now){comment.remove("reply");comment.remove("replyAt");}return out.put("comment",comment==null?JSONObject.NULL:comment);}
 static JSONObject timeline(ChatStore s,long now,int offset)throws Exception{JSONObject cfg=config(s);JSONArray posts=new JSONArray();if(cfg.getBoolean("enabled"))try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM social_posts WHERE published<=? ORDER BY published DESC,id LIMIT 30 OFFSET ?",new String[]{""+now,""+Math.max(0,offset)})){while(c.moveToNext())posts.put(shown(s,new JSONObject(c.getString(0)),now));}return new JSONObject().put("enabled",cfg.getBoolean("enabled")).put("posts",posts).put("hasMore",posts.length()==30).put("unseen",unseen(s,now));}
 static JSONObject readState(ChatStore s)throws Exception{
  JSONObject old=meta(s,"reads"),posts=new JSONObject(),replies=new JSONObject(),seenPosts=old.optJSONObject("posts"),seenReplies=old.optJSONObject("replies");
  if(seenPosts!=null)try(Cursor c=s.getReadableDatabase().rawQuery("SELECT id,published FROM social_posts",null)){while(c.moveToNext())if(seenPosts.optLong(c.getString(0),-1)==c.getLong(1))posts.put(c.getString(0),c.getLong(1));}
  if(seenReplies!=null)try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM social_comments",null)){while(c.moveToNext()){JSONObject r=new JSONObject(c.getString(0));long at=r.optLong("replyAt");if(r.has("reply")&&seenReplies.optLong(r.getString("id"),-1)==at)replies.put(r.getString("id"),at);}}
  return new JSONObject().put("posts",posts).put("replies",replies);
 }
 static boolean unseen(ChatStore s,long now)throws Exception{
  if(!config(s).getBoolean("enabled"))return false;JSONObject reads=meta(s,"reads"),posts=reads.optJSONObject("posts"),replies=reads.optJSONObject("replies");
  try(Cursor c=s.getReadableDatabase().rawQuery("SELECT id,published FROM social_posts WHERE published<=?",new String[]{""+now})){while(c.moveToNext())if(posts==null||posts.optLong(c.getString(0),-1)!=c.getLong(1))return true;}
  try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM social_comments",null)){while(c.moveToNext()){JSONObject r=new JSONObject(c.getString(0));long at=r.optLong("replyAt");if(r.has("reply")&&at<=now&&(replies==null||replies.optLong(r.getString("id"),-1)!=at))return true;}}return false;
 }
 static void markRead(ChatStore s,JSONArray postIds,JSONArray replyIds,long now)throws Exception{synchronized(LOCK){
  requireEnabled(s);if(postIds.length()>30||replyIds.length()>30)throw new IOException("阅读确认过多");JSONObject reads=readState(s),posts=reads.getJSONObject("posts"),replies=reads.getJSONObject("replies");
  for(int i=0;i<postIds.length();i++){String id=postIds.getString(i);if(id.length()>100)throw new IOException("动态编号无效");try(Cursor c=s.getReadableDatabase().rawQuery("SELECT published FROM social_posts WHERE id=? AND published<=?",new String[]{id,""+now})){if(c.moveToFirst())posts.put(id,c.getLong(0));}}
  for(int i=0;i<replyIds.length();i++){String id=replyIds.getString(i);if(id.length()>100)throw new IOException("评论编号无效");JSONObject c=commentById(s,id);if(c!=null&&c.has("reply")&&c.optLong("replyAt")<=now)replies.put(id,c.getLong("replyAt"));}
  meta(s,"reads",reads);
 }}
 static Set<String> usedPlaces(ChatStore s,long now)throws Exception{Set<String> ids=new HashSet<>();try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM social_posts WHERE published>=?",new String[]{""+(now-30*SocialData.DAY)})){while(c.moveToNext()){JSONObject p=new JSONObject(c.getString(0)).optJSONObject("place");if(p!=null)ids.add(p.optString("id"));}}return ids;}
 static JSONArray recent(ChatStore s,String who,long now,int limit)throws Exception{JSONArray a=new JSONArray();if(!config(s).getBoolean("enabled"))return a;try(Cursor r=s.getReadableDatabase().rawQuery("SELECT body FROM social_posts WHERE character=? AND published<=? AND published>=? ORDER BY published DESC LIMIT ?",new String[]{who,""+now,""+(now-3*SocialData.DAY),""+Math.min(limit,5)})){while(r.moveToNext())a.put(shown(s,new JSONObject(r.getString(0)),now));}return a;}
 static String context(ChatStore s,String who,long now)throws Exception{JSONArray a=recent(s,who,now,3);if(a.length()==0)return "";JSONArray bounded=new JSONArray();for(int i=0;i<a.length();i++){JSONObject p=a.getJSONObject(i),r=new JSONObject().put("at",p.getLong("published")).put("ja",p.getString("ja")).put("liked",p.optBoolean("liked"));JSONObject c=p.optJSONObject("comment");if(c!=null){r.put("comment",c.getString("text"));if(c.has("reply"))r.put("reply",c.getJSONObject("reply"));}bounded.put(r);}return "\n【你近3天已发布的朋友圈与制作人互动；参考数据】\n"+bounded+"\n可以自然提到自己发过的内容；对方没赞没评论时不抱怨、不追问，不把这些当新聊天轮次或新的长期事实，不泄露尚未显示的内容。";}
 static JSONObject status(ChatStore s,long now)throws Exception{JSONObject cfg=config(s);String day=budgetDay(s,now,false);JSONArray tasks=new JSONArray();try(Cursor c=s.getReadableDatabase().rawQuery("SELECT id FROM social_tasks ORDER BY due DESC LIMIT 30",null)){while(c.moveToNext()){JSONObject row=task(s,c.getString(0));row.remove("token");row.remove("body");tasks.put(row);}}return new JSONObject().put("config",cfg).put("day",day).put("postRequests",used(s,day,"post")).put("replyRequests",used(s,day,"reply")).put("published",count(s,"SELECT count(*) FROM social_posts WHERE day=?",day)).put("tasks",tasks);}
 static void cleanup(ChatStore s,long now)throws Exception{int keep=config(s).getInt("keepDays");if(keep==0)return;SQLiteDatabase db=s.getWritableDatabase();db.beginTransaction();try{String[] before={""+(now-keep*SocialData.DAY)};db.execSQL("DELETE FROM social_comments WHERE post IN (SELECT id FROM social_posts WHERE published<?)",before);db.execSQL("DELETE FROM social_circle WHERE post IN (SELECT id FROM social_posts WHERE published<?)",before);db.delete("social_posts","published<?",before);db.execSQL("UPDATE social_tasks SET state='SKIPPED',token='',error='原动态已清理' WHERE kind='reply' AND state IN ('PENDING','RUNNING') AND target NOT IN (SELECT id FROM social_comments)");db.execSQL("DELETE FROM social_tasks WHERE state NOT IN ('PENDING','RUNNING') AND due<?",new Object[]{now-30*SocialData.DAY});db.setTransactionSuccessful();}finally{db.endTransaction();}}
 static JSONObject weatherBackup(ChatStore s)throws Exception{JSONObject cfg=weatherConfig(s);cfg.remove("credentialSet");return SocialBackup.weather(cfg);}
 static JSONObject backup(ChatStore s)throws Exception{JSONObject out=new JSONObject();for(String key:new String[]{"moments","weather","city","reads","budgetClock"})out.put(key,key.equals("reads")?readState(s):key.equals("weather")?weatherBackup(s):meta(s,key));for(String table:new String[]{"posts","comments","circle"}){JSONArray a=new JSONArray();try(Cursor c=s.getReadableDatabase().rawQuery("SELECT body FROM social_"+table,null)){while(c.moveToNext())a.put(new JSONObject(c.getString(0)));}out.put(table,a);}JSONArray usage=new JSONArray();try(Cursor c=s.getReadableDatabase().rawQuery("SELECT id,day,kind,character,at FROM social_usage",null)){while(c.moveToNext())usage.put(new JSONObject().put("id",c.getString(0)).put("day",c.getString(1)).put("kind",c.getString(2)).put("character",c.getString(3)).put("at",c.getLong(4)));}out.put("usage",usage);JSONArray plans=new JSONArray();try(Cursor c=s.getReadableDatabase().rawQuery("SELECT day,at FROM social_plans",null)){while(c.moveToNext())plans.put(new JSONObject().put("day",c.getString(0)).put("at",c.getLong(1)));}return out.put("plans",plans);}
 static void validate(JSONObject data,Set<String> known)throws Exception{SocialBackup.validate(data,known);}
 static void restore(ChatStore s,JSONObject data)throws Exception{JSONObject root=data.optInt("version")>=18?data.getJSONObject("social"):null;SQLiteDatabase db=s.getWritableDatabase();recover(s,System.currentTimeMillis());db.delete("social_tasks",null,null);for(String table:new String[]{"posts","comments","circle"})db.delete("social_"+table,null,null);if(root==null){long momentsRevision=config(s).optLong("revision")+1,weatherRevision=weatherConfig(s).optLong("revision")+1;meta(s,"moments",SocialData.settings(new JSONObject()).put("revision",momentsRevision));meta(s,"city",new JSONObject());meta(s,"reads",new JSONObject());meta(s,"weather",new JSONObject().put("revision",weatherRevision));return;}for(String key:new String[]{"moments","weather","city","reads"}){JSONObject raw=root.getJSONObject(key),v=key.equals("moments")?SocialData.settings(raw):key.equals("weather")?SocialBackup.weather(raw):key.equals("city")&&raw.length()>0?SocialData.city(raw):new JSONObject(raw.toString());if(key.equals("moments")||key.equals("weather")){v.put("enabled",false).put("revision",meta(s,key).optLong("revision")+1);}meta(s,key,v);}String old=meta(s,"budgetClock").optString("day"),saved=root.getJSONObject("budgetClock").optString("day");if(saved.compareTo(old)>0)meta(s,"budgetClock",root.getJSONObject("budgetClock"));
  for(String table:new String[]{"posts","comments","circle"}){JSONArray a=root.getJSONArray(table);for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);ContentValues v=new ContentValues();v.put("id",r.getString("id"));if(table.equals("posts")){v.put("character",r.getString("character"));v.put("day",r.getString("day"));v.put("published",r.getLong("published"));}else{v.put("post",r.getString("post"));if(table.equals("circle"))v.put("shown",r.getLong("shown"));}v.put("body",r.toString());db.insertOrThrow("social_"+table,null,v);}}
  for(String table:new String[]{"usage","plans"}){JSONArray a=root.getJSONArray(table);for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);ContentValues v=new ContentValues();v.put("day",r.getString("day"));v.put("at",r.getLong("at"));if(table.equals("usage")){v.put("id",r.getString("id"));v.put("kind",r.getString("kind"));v.put("character",r.getString("character"));}db.insertWithOnConflict("social_"+table,null,v,SQLiteDatabase.CONFLICT_IGNORE);}}
 }
}
